<?php
namespace App\Domain\Documents\Resources;
use Illuminate\Http\Request;
use Illuminate\Http\Resources\Json\JsonResource;
class DocumentResource extends JsonResource { public function toArray(Request $request):array{return ['id'=>$this->id,'title'=>$this->title,'category'=>$this->category?->slug,'source'=>$this->source?->slug,'original_filename'=>$this->original_filename,'mime_type'=>$this->mime_type,'size'=>$this->size,'checksum'=>$this->checksum,'document_date'=>$this->document_date?->toDateString(),'issuer'=>$this->issuer,'status'=>$this->status instanceof \BackedEnum?$this->status->value:$this->status,'processing_status'=>$this->processing_status instanceof \BackedEnum?$this->processing_status->value:$this->processing_status,'archived_at'=>$this->archived_at?->toIso8601String(),'tags'=>$this->tags->pluck('name')->values(),'versions'=>$this->whenLoaded('versions',fn()=> $this->versions->map(fn($v)=>['id'=>$v->id,'version_number'=>$v->version_number,'original_filename'=>$v->original_filename,'mime_type'=>$v->mime_type,'size'=>$v->size,'checksum'=>$v->checksum,'created_at'=>$v->created_at?->toIso8601String()])),'created_at'=>$this->created_at?->toIso8601String(),'updated_at'=>$this->updated_at?->toIso8601String()];} }
